70	import jakarta.transaction.Transactional;
71	
72	/**
73	 * @author Vitaliy Fedoriv
74	 */
75	
76	@RestController
77	@CrossOrigin(exposedHeaders = "errors, content-type")
78	@RequestMapping("/api")
79	public class OwnerRestControllerV1 implements OwnersApi {
80	
81	    /**
82	     * Dedicated audit logger. On a successful owner create an audit line carrying the owner id,
83	     * the {@code customerCode} and the {@code registrationDate} is emitted to this named logger.
84	     */
85	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
86	
87	    private final ClinicService clinicService;
88	
89	    private final OwnerMapper ownerMapper;
90	
91	    private final PetMapper petMapper;
92	
93	    private final VisitMapper visitMapper;
94	
95	    private final HttpServletRequest request;
96	
97	    /**
98	     * The HTTP header carrying a client-supplied idempotency token for owner creation.
99	     */
100	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
101	
102	    /**
103	     * Remembers the owner originally created under each seen {@code Idempotency-Key}. A create that
104	     * repeats a key already present here is replayed - the stored owner is returned with 200 instead
105	     * of creating a duplicate.
106	     */
107	    private final Map<String, OwnerDto> idempotentCreates = new ConcurrentHashMap<>();
108	
109	    public OwnerRestControllerV1(ClinicService clinicService,
110	                                 OwnerMapper ownerMapper,
111	                                 PetMapper petMapper,
112	                                 VisitMapper visitMapper,
113	                                 HttpServletRequest request) {
114	        this.clinicService = clinicService;
115	        this.ownerMapper = ownerMapper;
116	        this.petMapper = petMapper;
117	        this.visitMapper = visitMapper;
118	        this.request = request;
119	    }
120	
121	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
122	    @Override
123	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
124	        Collection<Owner> owners;
125	        if (lastName != null) {
126	            owners = this.clinicService.findOwnerByLastName(lastName);
127	        } else {
128	            owners = this.clinicService.findAllOwners();
129	        }
130	        if (owners.isEmpty()) {
131	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
132	        }
133	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
134	    }
135	
136	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
137	    @Override
138	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
139	        Owner owner = this.clinicService.findOwnerById(ownerId);
140	        if (owner == null) {
141	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
142	        }
143	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
144	    }
145	
146	    /**
147	     * Rejects an owner payload that is missing or blank in any of the required fields
148	     * (firstName, lastName, address, city, telephone). Bean Validation on the request body
149	     * already rejects {@code null} values and empty strings, but treats a whitespace-only
150	     * value as present; this guard closes that gap so a blank in any required field is
151	     * reported. The thrown exception is translated to a 400 whose {@code errors} array lists
152	     * the name of each offending field.
153	     */
154	    private void rejectMissingOrBlankFields(OwnerFieldsDto ownerFieldsDto, String normalizedAddress) {
155	        List<String> missing = new ArrayList<>();
156	        if (isBlank(ownerFieldsDto.getFirstName())) {
157	            missing.add("firstName");
158	        }
159	        if (isBlank(ownerFieldsDto.getLastName())) {
160	            missing.add("lastName");
161	        }
162	        if (isBlank(normalizedAddress)) {
163	            missing.add("address");
164	        }
165	        if (isBlank(ownerFieldsDto.getCity())) {
166	            missing.add("city");
167	        }
168	        if (isBlank(ownerFieldsDto.getTelephone())) {
169	            missing.add("telephone");
170	        }
171	        if (!missing.isEmpty()) {
172	            throw new MissingOwnerFieldsException(missing);
173	        }
174	    }
175	
176	    private static boolean isBlank(String value) {
177	        return value == null || value.isBlank();
178	    }
179	
180	    /**
181	     * Matches a well-formed E.164 telephone: a leading '+' followed by 8 to 15 digits.
182	     */
183	    private static final Pattern E164_PATTERN = Pattern.compile("\\+\\d{8,15}");
184	
185	    /**
186	     * Required national-number length per country calling code. When the normalized E.164 number
187	     * begins with one of these codes, the digits that follow must number exactly the mapped value:
188	     * '+61' (Australia) requires 9 national digits and '+1' (NANP) requires 10. Codes absent from
189	     * this map carry no per-country length rule beyond the generic E.164 8-to-15-digit bound.
190	     */
191	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS = Map.of(
192	        "+61", 9,
193	        "+1", 10);
194	
195	    /**
196	     * Normalizes an owner's telephone on create into E.164 form. Spaces, dashes and brackets are
197	     * stripped. When a leading '+' (with its country code) is present it is kept as-is; otherwise
198	     * the country code '+61' is assumed and a single leading '0' is dropped from the national
199	     * digits. The result must be a '+' followed by 8 to 15 digits, so e.g. '0412 345 678' is
200	     * stored as '+61412345678'. When the country code has a known national-number length ('+61'
201	     * requires 9 national digits, '+1' requires 10) the national digits must match it exactly. A
202	     * value that cannot form a valid E.164 number, or whose national length is wrong for its
203	     * country, is rejected via {@link InvalidTelephoneException}, which the exception handler
204	     * translates to a 400.
205	     */
206	    private static String normalizeTelephone(String telephone) {
207	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()\\[\\]]", "");
208	        String e164;
209	        if (cleaned.startsWith("+")) {
210	            e164 = cleaned;
211	        } else {
212	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
213	            e164 = "+61" + national;
214	        }
215	        if (!E164_PATTERN.matcher(e164).matches()) {
216	            throw new InvalidTelephoneException(telephone);
217	        }
218	        for (Map.Entry<String, Integer> rule : NATIONAL_NUMBER_LENGTHS.entrySet()) {
219	            String code = rule.getKey();
220	            if (e164.startsWith(code)) {
221	                int nationalLength = e164.length() - code.length();
222	                if (nationalLength != rule.getValue()) {
223	                    throw new InvalidTelephoneException(telephone);
224	                }
225	                break;
226	            }
227	        }
228	        return e164;
229	    }
230	
231	    /**
232	     * Matches a well-formed postcode: exactly four digits.
233	     */
234	    private static final Pattern POSTCODE_PATTERN = Pattern.compile("\\d{4}");
235	
236	    /**
237	     * The canonical region for each city that has one. A city absent from this table has no known
238	     * region and so accepts any 4-digit postcode. This is the same fixed city-to-region table used
239	     * to derive an owner's locality.
240	     */
241	    private static final Map<String, String> CITY_REGION = Map.of(
242	        "Sydney", "NSW",
243	        "Melbourne", "VIC",
244	        "Brisbane", "QLD");
245	
246	    /**
247	     * The inclusive 4-digit postcode range for each region, as {@code {low, high}}: NSW 2000-2099,
248	     * VIC 3000-3099, QLD 4000-4099.
249	     */
250	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
251	        "NSW", new int[] {2000, 2099},
252	        "VIC", new int[] {3000, 3099},
253	        "QLD", new int[] {4000, 4099});
254	
255	    /**
256	     * Validates an owner's optional postcode. A {@code null} postcode is left as-is (the field is
257	     * optional). When present it must be exactly four digits; and when the owner's city maps to a
258	     * known region it must fall within that region's inclusive postcode range (NSW 2000-2099, VIC
259	     * 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit postcode. An
260	     * invalid or out-of-range value is rejected via {@link InvalidPostcodeException}, which the
261	     * exception handler translates to a 400.
262	     */
263	    private static void validatePostcode(String city, String postcode) {
264	        if (postcode == null) {
265	            return;
266	        }
267	        if (!POSTCODE_PATTERN.matcher(postcode).matches()) {
268	            throw new InvalidPostcodeException(postcode);
269	        }
270	        String region = CITY_REGION.get(city);
271	        if (region == null) {
272	            return;
273	        }
274	        int[] range = REGION_POSTCODES.get(region);
275	        int value = Integer.parseInt(postcode);
276	        if (value < range[0] || value > range[1]) {
277	            throw new InvalidPostcodeException(postcode);
278	        }
279	    }
280	
281	    /**
282	     * A pragmatic syntactic email check: a non-empty local part, an {@code @}, and a domain that
283	     * carries at least one dot, with no whitespace anywhere. Deliberately permissive — it accepts
284	     * ordinary addresses while rejecting obvious non-addresses such as one lacking an {@code @}.
285	     */
286	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
287	
288	    /**
289	     * Disposable-email domains that an owner's email may not use. An address whose domain (the part
290	     * after the final {@code @}, compared case-insensitively) is one of these is rejected. Kept as a
291	     * fixed set so the block list is explicit and easy to extend.
292	     */
293	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
294	        "mailinator.com",
295	        "tempmail.com",
296	        "guerrillamail.com");
297	
298	    /**
299	     * Normalizes an optional owner email. A {@code null} email is left as-is (the field is
300	     * optional). When present it must be a syntactically valid address whose domain is not on the
301	     * disposable-domain block list; a valid value is lower-cased so it is stored and returned in
302	     * canonical form. An invalid or disposable-domain value is rejected via
303	     * {@link InvalidEmailException}, which the exception handler translates to a 400.
304	     */
305	    private static String normalizeEmail(String email) {
306	        if (email == null) {
307	            return null;
308	        }
309	        if (!EMAIL_PATTERN.matcher(email).matches()) {
310	            throw new InvalidEmailException(email);
311	        }
312	        String normalized = email.toLowerCase(Locale.ROOT);
313	        String domain = normalized.substring(normalized.lastIndexOf('@') + 1);
314	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
315	            throw new InvalidEmailException(email);
316	        }
317	        return normalized;
318	    }
319	
320	    /**
321	     * The single derived identity of an owner, {@code normalizedTelephone + '|' + (email or empty)
322	     * + '|' + householdId}, into which all duplicate detection is consolidated. Two owners are the
323	     * same identity only when this whole key matches: because the normalized telephone is part of
324	     * the key, two members of the same household (same {@code householdId}) with different
325	     * telephones have different identity keys. A {@code null} email contributes an empty middle
326	     * segment. This is the value returned to callers as {@code identityKey}.
327	     */
328	    private static String identityKeyFor(String normalizedTelephone, String normalizedEmail, String householdId) {
329	        return normalizedTelephone + "|" + (normalizedEmail == null ? "" : normalizedEmail) + "|" + householdId;
330	    }
331	
332	    /**
333	     * Rejects a create whose derived identity collides with an existing owner's, reported via one
334	     * of the {@code Duplicate*} exceptions the handler translates to a 409. The former separate
335	     * telephone, email and household checks are now expressed through the components of the single
336	     * identity key:
337	     * <ul>
338	     *   <li>the normalized telephone matches an existing owner's canonical E.164 telephone (an
339	     *       existing value that cannot form a valid E.164 number is skipped rather than colliding);</li>
340	     *   <li>a present, lower-cased email matches an existing owner's lower-cased email (a {@code null}
341	     *       candidate email, being optional, is not compared, and existing owners without an email
342	     *       are skipped);</li>
343	     *   <li>the {@code householdId} matches an existing owner's - unless the caller opted into sharing
344	     *       a household via {@code sharesHousehold}, or the new owner carries a (distinguishing) email,
345	     *       in which case the household component is not compared. An email-bearing owner that shares a
346	     *       household is admitted as an implicit household member rather than rejected, and its
347	     *       {@code membershipLevel} is then capped one above the household's current maximum.</li>
348	     * </ul>
349	     */
350	    private void rejectDuplicateIdentity(OwnerFieldsDto ownerFieldsDto, String normalizedTelephone,
351	                                         String normalizedEmail, String householdId) {
352	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
353	        for (Owner existing : this.clinicService.findAllOwners()) {
354	            if (existing.isDeleted()) {
355	                continue;
356	            }
357	            String existingTelephone;
358	            try {
359	                existingTelephone = normalizeTelephone(existing.getTelephone());
360	            } catch (InvalidTelephoneException ex) {
361	                existingTelephone = null;
362	            }
363	            if (normalizedTelephone.equals(existingTelephone)) {
364	                throw new DuplicateTelephoneException(normalizedTelephone);
365	            }
366	            if (normalizedEmail != null) {
367	                String existingEmail = existing.getEmail();
368	                if (existingEmail != null && normalizedEmail.equals(existingEmail.toLowerCase(Locale.ROOT))) {
369	                    throw new DuplicateEmailException(normalizedEmail);
370	                }
371	            }
372	            if (!sharesHousehold && normalizedEmail == null
373	                && householdId.equals(householdIdFor(existing.getLastName(), existing.getPostcode()))) {
374	                throw new DuplicateHouseholdException(ownerFieldsDto.getLastName(), ownerFieldsDto.getPostcode());
375	            }
376	        }
377	    }
378	
379	    /**
380	     * Collapses a value for household comparison: leading and trailing whitespace is trimmed, any
381	     * internal run of whitespace is reduced to a single space, and the result is lower-cased. This
382	     * is how both {@code lastName} and {@code address} are compared so that differences of case or
383	     * spacing do not defeat the duplicate-household check.
384	     */
385	    private static String collapse(String value) {
386	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
387	    }
388	
389	    /**
390	     * Normalizes an owner's address into a canonical form applied on every create: leading and
391	     * trailing whitespace is trimmed, any internal run of whitespace is reduced to a single space,
392	     * the value is upper-cased, and common street-type abbreviations are expanded on a per-word
393	     * basis ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). The result is stored
394	     * and returned, and is the form every address comparison (duplicate-household detection and the
395	     * shared {@code householdId}) uses. A {@code null} or whitespace-only input normalizes to the
396	     * empty string, which the required-field guard then rejects. The transformation is idempotent,
397	     * so normalizing an already-normalized address is a no-op.
398	     */
399	    private static String normalizeAddress(String address) {
400	        if (address == null) {
401	            return "";
402	        }
403	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
404	        if (collapsed.isEmpty()) {
405	            return "";
406	        }
407	        String[] tokens = collapsed.split(" ");
408	        StringBuilder sb = new StringBuilder(collapsed.length());
409	        for (int i = 0; i < tokens.length; i++) {
410	            String token = tokens[i];
411	            switch (token) {
412	                case "ST" -> token = "STREET";
413	                case "RD" -> token = "ROAD";
414	                case "AVE" -> token = "AVENUE";
415	                default -> {
416	                }
417	            }
418	            if (i > 0) {
419	                sb.append(' ');
420	            }
421	            sb.append(token);
422	        }
423	        return sb.toString();
424	    }
425	
426	    /**
427	     * Derives an owner's region code from its postcode, falling back to its city. A present postcode
428	     * that falls in a known region's inclusive 4-digit range wins (NSW 2000-2099, VIC 3000-3099, QLD
429	     * 4000-4099); otherwise the fixed city-to-region table is consulted (Sydney -> NSW, Melbourne ->
430	     * VIC, Brisbane -> QLD); a value resolved by neither is {@code "UNKNOWN"}. This is the single
431	     * region derivation shared by the {@code customerCode} and the owner's locality.
432	     */
433	    private static String deriveRegion(String city, String postcode) {
434	        if (postcode != null) {
435	            try {
436	                int pc = Integer.parseInt(postcode.trim());
437	                for (Map.Entry<String, int[]> range : REGION_POSTCODES.entrySet()) {
438	                    int[] bounds = range.getValue();
439	                    if (pc >= bounds[0] && pc <= bounds[1]) {
440	                        return range.getKey();
441	                    }
442	                }
443	            } catch (NumberFormatException ignored) {
444	                // not a numeric postcode; fall back to the city-to-region table
445	            }
446	        }
447	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
448	    }
449	
450	    /**
451	     * Builds the {@code customerCode} for a newly created owner, formatted {@code '<REGION>-<HASH8>'}
452	     * where {@code REGION} is the region code derived from the owner's postcode (falling back to its
453	     * city) and {@code HASH8} is the first 8 upper-case hex characters of SHA-256 over
454	     * {@code normalizedTelephone + lastName} (e.g. {@code 'NSW-1A2B3C4D'}). This is a stable identity:
455	     * it carries no sequence number and depends only on the owner's own region, telephone and surname.
456	     */
457	    private static String customerCodeFor(String region, String normalizedTelephone, String lastName) {
458	        return region + "-" + sha256HexPrefix(normalizedTelephone + lastName, 8);
459	    }
460	
461	    /**
462	     * De-duplicates a freshly computed {@code customerCode} against the codes already carried by
463	     * existing owners. When the base code is unused it is returned unchanged; otherwise
464	     * {@code '-<n>'} is appended with the smallest {@code n} of 2 or more that yields a code no
465	     * existing owner already holds. The count reflects the state prior to this create.
466	     */
467	    private String deduplicateCustomerCode(String baseCode) {
468	        Set<String> existingCodes = new HashSet<>();
469	        for (Owner existing : this.clinicService.findAllOwners()) {
470	            String code = existing.getCustomerCode();
471	            if (code != null) {
472	                existingCodes.add(code);
473	            }
474	        }
475	        if (!existingCodes.contains(baseCode)) {
476	            return baseCode;
477	        }
478	        int n = 2;
479	        while (existingCodes.contains(baseCode + "-" + n)) {
480	            n++;
481	        }
482	        return baseCode + "-" + n;
483	    }
484	
485	    /**
486	     * Returns the first {@code hexChars} upper-case hex characters of the SHA-256 digest of the UTF-8
487	     * bytes of {@code value}.
488	     */
489	    private static String sha256HexPrefix(String value, int hexChars) {
490	        try {
491	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
492	            StringBuilder sb = new StringBuilder(hexChars);
493	            for (byte b : digest) {
494	                if (sb.length() >= hexChars) {
495	                    break;
496	                }
497	                sb.append(String.format("%02X", b));
498	            }
499	            return sb.substring(0, hexChars);
500	        } catch (NoSuchAlgorithmException ex) {
501	            throw new IllegalStateException("SHA-256 not available", ex);
502	        }
503	    }
504	
505	    /**
506	     * Builds the {@code membershipNumber} for a newly created owner, formatted
507	     * {@code '<customerCode>-M<YY>'} where {@code YY} is the last two digits of the
508	     * fiscal year of the {@code registrationDate} (e.g. {@code 'SMI-0007-M27'}). The year
509	     * segment therefore matches the owner's {@code fiscalYear}.
510	     */
511	    private static String membershipNumberFor(String customerCode, LocalDate registrationDate) {
512	        return String.format("%s-M%02d", customerCode, fiscalYearOf(registrationDate) % 100);
513	    }
514	
515	    /**
516	     * The fiscal year, as a four-digit year, of a business-day-adjusted date. The fiscal year
517	     * starts on 1 July and is labelled by the calendar year in which it ends: a date on or after
518	     * 1 July belongs to the fiscal year ending the following calendar year, while an earlier date
519	     * belongs to the fiscal year ending in its own year.
520	     */
521	    private static int fiscalYearOf(LocalDate date) {
522	        return date.getMonthValue() >= Month.JULY.getValue() ? date.getYear() + 1 : date.getYear();
523	    }
524	
525	    /**
526	     * Derives the stable {@code householdId} for an owner from the collapsed {@code lastName} and
527	     * its {@code postcode} - the same pair used to detect a shared household. It is the first 12
528	     * lower-case hex characters of SHA-256 over {@code normalizedLastName + '|' + postcode}. Because
529	     * it is a pure function of that pair, every owner in the same household - whether created first
530	     * or joining later via {@code sharesHousehold} - receives the identical, non-blank identifier
531	     * without needing to read any other owner's value. A {@code null} postcode contributes an empty
532	     * segment.
533	     */
534	    private static String householdIdFor(String lastName, String postcode) {
535	        String key = collapse(lastName) + "|" + (postcode == null ? "" : postcode);
536	        try {
537	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
538	            StringBuilder sb = new StringBuilder(12);
539	            for (byte b : digest) {
540	                if (sb.length() >= 12) {
541	                    break;
542	                }
543	                sb.append(String.format("%02x", b));
544	            }
545	            return sb.substring(0, 12);
546	        } catch (NoSuchAlgorithmException ex) {
547	            throw new IllegalStateException("SHA-256 not available", ex);
548	        }
549	    }
550	
551	    /**
552	     * Counts the existing owners who already share the given {@code firstName} and {@code lastName},
553	     * compared case-insensitively. This is evaluated before the new owner is saved, so it reflects
554	     * the state prior to this create and is stored on the owner as its {@code namesakeCount}.
555	     */
556	    private int countNamesakes(String firstName, String lastName) {
557	        int count = 0;
558	        for (Owner existing : this.clinicService.findAllOwners()) {
559	            if (firstName.equalsIgnoreCase(existing.getFirstName())
560	                && lastName.equalsIgnoreCase(existing.getLastName())) {
561	                count++;
562	            }
563	        }
564	        return count;
565	    }
566	
567	    /**
568	     * Counts the members of the household the new owner will belong to, as it stands after this
569	     * create. Every existing owner carrying the same {@code householdId} is counted, and the new
570	     * owner itself is added, so a value of 3 or more means the owner joins a household of at least
571	     * three members. This is evaluated with the new owner's {@code householdId} already set and is
572	     * stored on the owner as its {@code householdMemberCount}.
573	     */
574	    private int countHouseholdMembers(String householdId) {
575	        int count = 1;
576	        for (Owner existing : this.clinicService.findAllOwners()) {
577	            if (householdId.equals(existing.getHouseholdId())) {
578	                count++;
579	            }
580	        }
581	        return count;
582	    }
583	
584	    /**
585	     * Finds an existing owner that makes the new owner a <em>possible</em> (soft) duplicate: one
586	     * that is not a hard identity collision but shares the new owner's {@code lastName} (compared
587	     * case-insensitively) and {@code postcode} while carrying a different normalized telephone. The
588	     * new owner's postcode must be present for a soft match to be possible. When several existing
589	     * owners qualify the one with the lowest id is chosen. Returns the matching owner's id, or
590	     * {@code null} when there is no soft match. This is evaluated after the hard-duplicate check has
591	     * already passed, so any owner sharing the lastName and postcode necessarily differs in telephone.
592	     *
593	     * <p>Because the household is now keyed on {@code (lastName, postcode)} - exactly the soft-match
594	     * key - a co-member reached here can only be one the caller declared via {@code sharesHousehold}
595	     * (otherwise the hard household-duplicate check would already have rejected it). A declared
596	     * household member is not a suspected duplicate, so no soft match is reported in that case.
597	     */
598	    private Integer findPossibleDuplicateOf(OwnerFieldsDto ownerFieldsDto, String normalizedTelephone) {
599	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
600	            return null;
601	        }
602	        String postcode = ownerFieldsDto.getPostcode();
603	        if (postcode == null) {
604	            return null;
605	        }
606	        String lastName = ownerFieldsDto.getLastName();
607	        Integer matchId = null;
608	        for (Owner existing : this.clinicService.findAllOwners()) {
609	            if (existing.isDeleted()) {
610	                continue;
611	            }
612	            if (lastName == null || !lastName.equalsIgnoreCase(existing.getLastName())) {
613	                continue;
614	            }
615	            if (!postcode.equals(existing.getPostcode())) {
616	                continue;
617	            }
618	            String existingTelephone;
619	            try {
620	                existingTelephone = normalizeTelephone(existing.getTelephone());
621	            } catch (InvalidTelephoneException ex) {
622	                existingTelephone = null;
623	            }
624	            if (normalizedTelephone.equals(existingTelephone)) {
625	                continue;
626	            }
627	            if (existing.getId() != null && (matchId == null || existing.getId() < matchId)) {
628	                matchId = existing.getId();
629	            }
630	        }
631	        return matchId;
632	    }
633	
634	    /**
635	     * The tenure, in elapsed fiscal years, that an owner must exceed before its tenure contributes
636	     * membership points. Tenure is measured from the owner's {@code registrationDate}, so a newly
637	     * created owner (whose tenure is zero) never satisfies this and thus never earns the tenure
638	     * points on create.
639	     */
640	    private static final int TENURE_POINTS_THRESHOLD_FISCAL_YEARS = 1;
641	
642	    /**
643	     * The household size (number of members) at or above which an owner earns the household points.
644	     */
645	    private static final int HOUSEHOLD_POINTS_THRESHOLD = 3;
646	
647	    /**
648	     * Computes the {@code membershipPoints} for an owner. Points start at 0, gain 2 when an email is
649	     * present, gain 1 when the owner's {@code namesakeCount} is 0, gain 2 when the owner's household
650	     * has {@value #HOUSEHOLD_POINTS_THRESHOLD} or more members, and gain 3 when the owner's tenure
651	     * (elapsed fiscal years since its {@code registrationDate}) exceeds
652	     * {@value #TENURE_POINTS_THRESHOLD_FISCAL_YEARS}. Because a newly created owner has zero tenure,
653	     * the tenure points never apply on create.
654	     * Evaluated after the owner's email, namesakeCount, householdMemberCount and registrationDate
655	     * have been set.
656	     */
657	    private static int membershipPointsFor(Owner owner) {
658	        int points = 0;
659	        if (owner.getEmail() != null && !owner.getEmail().isEmpty()) {
660	            points += 2;
661	        }
662	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
663	            points += 1;
664	        }
665	        if (owner.getHouseholdMemberCount() != null
666	            && owner.getHouseholdMemberCount() >= HOUSEHOLD_POINTS_THRESHOLD) {
667	            points += 2;
668	        }
669	        if (tenureInFiscalYears(owner) > TENURE_POINTS_THRESHOLD_FISCAL_YEARS) {
670	            points += 3;
671	        }
672	        return points;
673	    }
674	
675	    /**
676	     * Maps {@code membershipPoints} to the numeric {@code membershipLevel}: level 1 for 0-1 points,
677	     * 2 for 2-3, 3 for 4-5, and 4 for 6 or more points.
678	     */
679	    private static int membershipLevelForPoints(int points) {
680	        if (points <= 1) {
681	            return 1;
682	        }
683	        if (points <= 3) {
684	            return 2;
685	        }
686	        if (points <= 5) {
687	            return 3;
688	        }
689	        return 4;
690	    }
691	
692	    /**
693	     * Caps a newly computed {@code membershipLevel} so it never exceeds one above the current maximum
694	     * {@code membershipLevel} among the new owner's household members - the existing, non-deleted
695	     * owners already carrying the same {@code householdId}. When the household has no existing member
696	     * (or none with a recorded level) no cap applies and the level is returned unchanged; otherwise the
697	     * level is limited to {@code max(member level) + 1}. The count reflects the state prior to this
698	     * create, as the new owner has not yet been saved.
699	     */
700	    private int capMembershipLevelByHousehold(int membershipLevel, String householdId) {
701	        Integer maxMemberLevel = null;
702	        for (Owner existing : this.clinicService.findAllOwners()) {
703	            if (existing.isDeleted()) {
704	                continue;
705	            }
706	            if (!householdId.equals(existing.getHouseholdId())) {
707	                continue;
708	            }
709	            Integer existingLevel = existing.getMembershipLevel();
710	            if (existingLevel == null) {
711	                continue;
712	            }
713	            if (maxMemberLevel == null || existingLevel > maxMemberLevel) {
714	                maxMemberLevel = existingLevel;
715	            }
716	        }
717	        if (maxMemberLevel == null) {
718	            return membershipLevel;
719	        }
720	        return Math.min(membershipLevel, maxMemberLevel + 1);
721	    }
722	
723	    /**
724	     * The owner's tenure in whole elapsed fiscal years: the number of 1 July fiscal-year boundaries
725	     * crossed between its {@code registrationDate} and the current server date. An owner with no
726	     * registration date, or one dated in the future, has a tenure of zero.
727	     */
728	    private static long tenureInFiscalYears(Owner owner) {
729	        LocalDate registrationDate = owner.getRegistrationDate();
730	        if (registrationDate == null) {
731	            return 0;
732	        }
733	        return Math.max(0, fiscalYearOf(LocalDate.now()) - fiscalYearOf(registrationDate));
734	    }
735	
736	    /**
737	     * The maximum number of owners any single city may contain. A create whose city already
738	     * holds this many owners is rejected.
739	     */
740	    private static final int CITY_CAPACITY = 50;
741	
742	    /**
743	     * Rejects a create whose city already contains {@value #CITY_CAPACITY} or more owners,
744	     * compared case-insensitively - the same way the city is matched when building the
745	     * {@code customerCode} sequence. The count reflects the state prior to this create. A city
746	     * at capacity is reported via {@link CityAtCapacityException}, which the exception handler
747	     * translates to a 409.
748	     */
749	    private void rejectCityAtCapacity(String city) {
750	        int count = 0;
751	        for (Owner existing : this.clinicService.findAllOwners()) {
752	            if (city.equalsIgnoreCase(existing.getCity())) {
753	                count++;
754	            }
755	        }
756	        if (count >= CITY_CAPACITY) {
757	            throw new CityAtCapacityException(city);
758	        }
759	    }
760	
761	    /**
762	     * The maximum number of owners that may be created on any single day (by
763	     * {@code registrationDate}). A create attempted once this many owners already carry the
764	     * current day's registration date is rejected.
765	     */
766	    private static final int DAILY_OWNER_LIMIT = 100;
767	
768	    /**
769	     * Rejects a create once {@value #DAILY_OWNER_LIMIT} or more owners already carry the given
770	     * business-day-adjusted {@code registrationDate} (the date the new owner will itself receive).
771	     * The count reflects the state prior to this create. When the limit is reached the create is
772	     * reported via {@link DailyOwnerLimitExceededException}, which the exception handler translates
773	     * to a 429 Too Many Requests.
774	     */
775	    private void rejectDailyOwnerLimit(LocalDate registrationDate) {
776	        int count = 0;
777	        for (Owner existing : this.clinicService.findAllOwners()) {
778	            if (registrationDate.equals(existing.getRegistrationDate())) {
779	                count++;
780	            }
781	        }
782	        if (count >= DAILY_OWNER_LIMIT) {
783	            throw new DailyOwnerLimitExceededException();
784	        }
785	    }
786	
787	    /**
788	     * The number of owners that must already carry a given {@code registrationDate} before a
789	     * create on that date is flagged with a bulk-signup warning. Once <em>more than</em> this
790	     * many owners already exist for the day, the new owner's {@code bulkSignupWarning} is true.
791	     */
792	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
793	
794	    /**
795	     * Computes the {@code bulkSignupWarning} for a create on the given business-day-adjusted
796	     * {@code registrationDate}: true when more than {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners
797	     * have already been created for that date, otherwise false. The count reflects the state prior
798	     * to this create, matching how the daily-limit rule accumulates.
799	     */
800	    private boolean bulkSignupWarningFor(LocalDate registrationDate) {
801	        int count = 0;
802	        for (Owner existing : this.clinicService.findAllOwners()) {
803	            if (registrationDate.equals(existing.getRegistrationDate())) {
804	                count++;
805	            }
806	        }
807	        return count > BULK_SIGNUP_WARNING_THRESHOLD;
808	    }
809	
810	    /**
811	     * Rolls an effective registration date forward onto a business day. A Saturday, Sunday or listed
812	     * public holiday is advanced to the next non-holiday business day; a plain weekday is returned
813	     * unchanged. This is applied to the effective registration date - whether supplied in the request
814	     * or defaulted to the server date - so the stored {@code registrationDate}, and everything derived
815	     * from it, always falls on a business day.
816	     */
817	    /**
818	     * Rejects a supplied {@code registrationDate} that lies in the future. A registration date is
819	     * only ever explicitly supplied on the request; when present it must not be later than the
820	     * current server date. A future date raises a {@link FutureRegistrationDateException}, which the
821	     * exception handler translates to a 400 Bad Request. A {@code null} date (the default, filled in
822	     * later from the server date) is accepted.
823	     */
824	    private static void rejectFutureRegistrationDate(LocalDate registrationDate) {
825	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
826	            throw new FutureRegistrationDateException(registrationDate);
827	        }
828	    }
829	
830	    /**
831	     * The fixed list of public holidays. An effective registration date that lands on any of these
832	     * is rolled forward, together with weekends, to the next non-holiday business day.
833	     */
834	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
835	        LocalDate.of(2026, 1, 1),
836	        LocalDate.of(2026, 1, 26),
837	        LocalDate.of(2026, 4, 25),
838	        LocalDate.of(2026, 12, 25),
839	        LocalDate.of(2026, 12, 28));
840	
841	    private static LocalDate toBusinessDay(LocalDate date) {
842	        while (isWeekend(date) || PUBLIC_HOLIDAYS.contains(date)) {
843	            date = date.plusDays(1);
844	        }
845	        return date;
846	    }
847	
848	    private static boolean isWeekend(LocalDate date) {
849	        return switch (date.getDayOfWeek()) {
850	            case SATURDAY, SUNDAY -> true;
851	            default -> false;
852	        };
853	    }
