856	    @Override
857	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
858	        String idempotencyKey = request.getHeader(IDEMPOTENCY_KEY_HEADER);
859	        if (idempotencyKey != null && !idempotencyKey.isBlank()) {
860	            OwnerDto replay = idempotentCreates.get(idempotencyKey);
861	            if (replay != null) {
862	                return new ResponseEntity<>(replay, HttpStatus.OK);
863	            }
864	        }
865	        String normalizedLine1 = null;
866	        String normalizedLine2 = null;
867	        String composedAddress;
868	        if (!isBlank(ownerFieldsDto.getAddressLine1())) {
869	            normalizedLine1 = normalizeAddress(ownerFieldsDto.getAddressLine1());
870	            if (!isBlank(ownerFieldsDto.getAddressLine2())) {
871	                normalizedLine2 = normalizeAddress(ownerFieldsDto.getAddressLine2());
872	            }
873	            composedAddress = normalizedLine2 == null
874	                ? normalizedLine1
875	                : normalizedLine1 + " " + normalizedLine2;
876	        } else {
877	            composedAddress = normalizeAddress(ownerFieldsDto.getAddress());
878	        }
879	        rejectMissingOrBlankFields(ownerFieldsDto, composedAddress);
880	        rejectCityAtCapacity(ownerFieldsDto.getCity());
881	        HttpHeaders headers = new HttpHeaders();
882	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
883	        owner.setAddress(composedAddress);
884	        owner.setAddressLine1(normalizedLine1);
885	        owner.setAddressLine2(normalizedLine2);
886	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
887	        owner.setTelephone(normalizedTelephone);
888	        String normalizedEmail = normalizeEmail(ownerFieldsDto.getEmail());
889	        owner.setEmail(normalizedEmail);
890	        validatePostcode(owner.getCity(), owner.getPostcode());
891	        String householdId = householdIdFor(owner.getLastName(), owner.getPostcode());
892	        rejectDuplicateIdentity(ownerFieldsDto, normalizedTelephone, normalizedEmail, householdId);
893	        rejectFutureRegistrationDate(owner.getRegistrationDate());
894	        LocalDate effectiveDate = owner.getRegistrationDate() == null ? LocalDate.now() : owner.getRegistrationDate();
895	        LocalDate registrationDate = toBusinessDay(effectiveDate);
896	        rejectDailyOwnerLimit(registrationDate);
897	        owner.setBulkSignupWarning(bulkSignupWarningFor(registrationDate));
898	        owner.setRegistrationDate(registrationDate);
899	        String region = deriveRegion(owner.getCity(), owner.getPostcode());
900	        owner.setCustomerCode(deduplicateCustomerCode(customerCodeFor(region, normalizedTelephone, owner.getLastName())));
901	        owner.setMembershipNumber(membershipNumberFor(owner.getCustomerCode(), owner.getRegistrationDate()));
902	        owner.setHouseholdId(householdId);
903	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
904	        owner.setHouseholdMemberCount(countHouseholdMembers(owner.getHouseholdId()));
905	        int membershipPoints = membershipPointsFor(owner);
906	        owner.setMembershipPoints(membershipPoints);
907	        int membershipLevel = membershipLevelForPoints(membershipPoints);
908	        // A declared household member (sharesHousehold) keeps its point-derived level; an owner
909	        // admitted into an existing household implicitly has its level capped one above the
910	        // household's current maximum.
911	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
912	            membershipLevel = capMembershipLevelByHousehold(membershipLevel, owner.getHouseholdId());
913	        }
914	        owner.setMembershipLevel(membershipLevel);
915	        Integer possibleDuplicateOf = findPossibleDuplicateOf(ownerFieldsDto, normalizedTelephone);
916	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
917	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
918	        this.clinicService.saveOwner(owner);
919	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
920	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel(), owner.getMembershipNumber());
921	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
922	        if (idempotencyKey != null && !idempotencyKey.isBlank()) {
923	            idempotentCreates.put(idempotencyKey, ownerDto);
924	        }
925	        headers.setLocation(UriComponentsBuilder.newInstance()
926	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
927	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
928	    }
