57	     * {@code REGION} portion is the segment before the first {@code '-'} (e.g. {@code "NSW-1A2B3C4D"}
58	     * yields {@code "NSW"}). This shares the identity's region derivation, where the postcode range
59	     * takes precedence (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099) and the city-to-region table is
60	     * the fallback. For an owner without a {@code customerCode} the same region is recomputed directly
61	     * from the postcode then city, otherwise "UNKNOWN".
62	     */
63	    default String deriveLocality(Owner owner) {
64	        if (owner == null) {
65	            return null;
66	        }
67	        String customerCode = owner.getCustomerCode();
68	        if (customerCode != null) {
69	            int dash = customerCode.indexOf('-');
70	            if (dash > 0) {
