90	            }
91	        }
92	        String city = owner.getCity();
93	        if ("Sydney".equals(city)) {
94	            return "NSW";
95	        }
96	        if ("Melbourne".equals(city)) {
97	            return "VIC";
98	        }
99	        if ("Brisbane".equals(city)) {
100	            return "QLD";
101	        }
102	        return "UNKNOWN";
103	    }
