106	     * Derive the owner's IANA timezone from its locality/region using the fixed region-to-timezone
107	     * table (NSW->Australia/Sydney, VIC->Australia/Melbourne, QLD->Australia/Brisbane). The region is
108	     * the same value reported as {@code locality}. Returns null when the owner is absent or the region
109	     * has no known timezone.
110	     */
111	    default String deriveTimezone(Owner owner) {
112	        if (owner == null) {
113	            return null;
114	        }
115	        String region = deriveLocality(owner);
116	        if ("NSW".equals(region)) {
