131	     * Returns null when the owner or its customerCode is absent.
132	     */
133	    default Integer deriveCheckDigit(Owner owner) {
134	        if (owner == null || owner.getCustomerCode() == null) {
135	            return null;
136	        }
137	        String code = owner.getCustomerCode();
138	        int sum = 0;
139	        boolean dbl = true;
140	        for (int i = code.length() - 1; i >= 0; i--) {
141	            char c = code.charAt(i);
142	            if (c < '0' || c > '9') {
143	                continue;
144	            }
145	            int d = c - '0';
146	            if (dbl) {
147	                d *= 2;
148	                if (d > 9) {
149	                    d -= 9;
150	                }
151	            }
152	            sum += d;
153	            dbl = !dbl;
154	        }
155	        return (10 - (sum % 10)) % 10;
156	    }
