158	    /**
159	     * Derive the owner's age band from its birthDate against the registrationDate: 'MINOR' when
160	     * under 18, 'ADULT' from 18 to 64, and 'SENIOR' at 65 or older. The age is the number of whole
161	     * years between birthDate and registrationDate (falling back to the current date when the owner
162	     * has no registrationDate). Returns null when the owner or its birthDate is absent, so no
163	     * ageBand is reported.
164	     */
165	    default String deriveAgeBand(Owner owner) {
166	        if (owner == null || owner.getBirthDate() == null) {
167	            return null;
168	        }
169	        java.time.LocalDate reference = owner.getRegistrationDate() != null
170	            ? owner.getRegistrationDate() : java.time.LocalDate.now();
171	        int age = java.time.Period.between(owner.getBirthDate(), reference).getYears();
172	        if (age < 18) {
173	            return "MINOR";
174	        }
175	        if (age < 65) {
176	            return "ADULT";
177	        }
178	        return "SENIOR";
179	    }
180	
181	    /**
182	     * Known E.164 country calling codes, longest first, used to split a stored telephone into its
183	     * country code and national digits. A number whose code is not listed falls back to a two-digit
184	     * country code, the most common E.164 length.
185	     */
186	    String[] KNOWN_CALLING_CODES = { "61", "1" };
187	
188	    /**
189	     * Format the owner's stored E.164 {@code telephone} for humans: the country code, a space, then
190	     * the national digits grouped in threes (e.g. {@code "+61412345678"} becomes
191	     * {@code "+61 412 345 678"}). Returns null when the owner or its telephone is absent, and returns
192	     * the value unchanged when it is not in E.164 form.
193	     */
194	    default String deriveTelephoneDisplay(Owner owner) {
195	        if (owner == null || owner.getTelephone() == null) {
196	            return null;
197	        }
198	        String telephone = owner.getTelephone();
199	        if (!telephone.startsWith("+")) {
200	            return telephone;
201	        }
202	        String digits = telephone.substring(1);
203	        int codeLength = 2;
204	        for (String code : KNOWN_CALLING_CODES) {
205	            if (digits.startsWith(code) && digits.length() > code.length()) {
206	                codeLength = code.length();
207	                break;
208	            }
209	        }
210	        if (digits.length() <= codeLength) {
211	            return telephone;
212	        }
213	        String national = digits.substring(codeLength);
214	        StringBuilder display = new StringBuilder("+").append(digits, 0, codeLength);
215	        for (int i = 0; i < national.length(); i += 3) {
216	            display.append(' ').append(national, i, Math.min(i + 3, national.length()));
217	        }
218	        return display.toString();
219	    }
220	
221	    /**
222	     * Derive the owner's salutation: the honorific {@code title} followed by a single space and the
223	     * {@code lastName} (e.g. {@code "DR Who"}). When the owner has no title (null or blank) the
224	     * salutation is just the {@code lastName}. Returns null when the owner is absent.
225	     */
226	    default String deriveSalutation(Owner owner) {
227	        if (owner == null) {
228	            return null;
229	        }
230	        String title = owner.getTitle();
231	        String lastName = owner.getLastName();
232	        if (title == null || title.isBlank()) {
233	            return lastName;
234	        }
235	        return title + " " + lastName;
236	    }
237	
238	    /**
239	     * Derive the owner's fiscal year from its business-day-adjusted {@code registrationDate},
240	     * formatted {@code 'FY<YY>'} where YY is the last two digits of the fiscal year. The fiscal
241	     * year starts on 1 July and is labelled by the calendar year in which it ends, so a
242	     * registrationDate on or after 1 July belongs to the fiscal year ending the following calendar
243	     * year. Returns null when the owner or its registrationDate is absent.
244	     */
245	    default String deriveFiscalYear(Owner owner) {
246	        if (owner == null || owner.getRegistrationDate() == null) {
247	            return null;
248	        }
249	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
250	        int fiscalYear = registrationDate.getMonthValue() >= java.time.Month.JULY.getValue()
251	            ? registrationDate.getYear() + 1 : registrationDate.getYear();
252	        return String.format("FY%02d", fiscalYear % 100);
253	    }
254	
255	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
256	        OwnerPageDto ownerPageDto = new OwnerPageDto();
257	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
258	        ownerPageDto.setPage(ownerPage.getNumber());
259	        ownerPageDto.setSize(ownerPage.getSize());
260	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
261	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
262	        return ownerPageDto;
263	    }
264	}
